#include "eternity/game/quest_save.hpp"
#include "eternity/game/skill_save.hpp"
#include "eternity/game/character_core_save.hpp"
#include "eternity/game/inventory_save.hpp"
#include "eternity/game/creation.hpp"
#include <iostream>

using namespace eternity;using namespace eternity::game;
namespace {
void require(bool value,const char* message) {if(!value) throw std::runtime_error(message);}
void put(net::Packet& p,std::uint32_t value,unsigned int bytes) {for(unsigned int i=0;i<bytes;++i) p.push_back(static_cast<std::uint8_t>(value>>(8*i)));}
net::Packet packet(std::uint16_t op,std::uint32_t account=9301) {net::Packet p;put(p,op,2);put(p,account,4);return p;}
net::Packet start(std::uint16_t id,std::uint16_t delay,std::uint32_t account=9301) {auto p=packet(0xa01,account);put(p,id,2);put(p,delay,2);return p;}
net::Packet end(std::uint16_t id,std::uint8_t success) {auto p=packet(0xa02);put(p,id,2);p.push_back(success);return p;}
net::Packet progress(std::uint16_t id,std::uint16_t delay,std::initializer_list<std::uint8_t> counters) {auto p=packet(0xa03);put(p,id,2);put(p,delay,2);p.insert(p.end(),counters);return p;}
net::Packet skill(std::uint16_t id,std::uint16_t points) {auto p=packet(0x801);put(p,points,2);put(p,id,2);p.push_back(1);return p;}
}
int main(int argc,char** argv) {
    try {
        require(argc==2 && std::string_view(argv[1]).starts_with("Eternity_Test_Creation_"),"Quest SQL test requires disposable catalog");const std::string catalog=argv[1],prefix="["+catalog+"].dbo.";
        storage::SqlServer db(storage::SqlServerConfig::from_environment());const auto definitions=Definitions::load(db);const auto rules=CreationRules::load(definitions);const auto time=std::chrono::sys_days{std::chrono::year{2024}/1/1};Characters characters(db,1,time,catalog);require(characters.save_country(9301,0,true) && characters.save_country(9302,0,true),"Cannot initialize quest fixture factions");auto draft=rules.prepare({0,0,0,0,0,0,0,0,"QuestHero"},0);draft.items.clear();const auto created=characters.create(9301,"quest_user",draft,time);draft.request.name="QuestOther";const auto other=characters.create(9302,"quest_other",draft,time);require(created.result==0 && other.result==0,"Cannot create quest fixture characters");const auto cid=std::to_string(created.character_id),other_id=std::to_string(other.character_id);
        db.query("EXEC "+prefix+"usp_Save_Char_Quest_Add_E "+cid+",10,9,1,2,3; EXEC "+prefix+"usp_Save_Char_Quest_Add_E "+cid+",11,17,4,5,6; EXEC "+prefix+"usp_Save_Char_Quest_Add_E "+cid+",12,19,7,8,9; EXEC "+prefix+"usp_Save_Char_FinishedQuest_E "+cid+",20,1,1; EXEC "+prefix+"usp_Save_Char_FinishedQuest_E "+other_id+",99,1,1;");
        PlayerCore core;core.user_id=9301;core.character=draft.character;core.character.id=created.character_id;core.skill_points=40;InventoryReplicaPool pool;CharacterReplica cache(core,pool);
        require(cache.quests().load({10,9,{1,2,3}}) && cache.quests().load({11,17,{4,5,6}}) && cache.quests().load({12,19,{7,8,9}}) && cache.quests().load_finished({20,1}),"Cannot load quest fixture");
        CharacterCoreStore core_store(db,catalog);InventoryStore items(db,1,catalog);SkillStore skills(db,catalog);QuestStore quests(db,catalog);const auto apply=[&](const net::Packet& p){require(cache.apply(p)==InventoryReplicaResult::applied,"Quest fixture command failed");};
        const auto save=[&](){core_store.save_in_transaction(cache);items.save_in_transaction(cache.inventory(),created.character_id);skills.save_in_transaction(cache.skills(),created.character_id);quests.save_in_transaction(cache.quests(),created.character_id);};
        const auto acknowledge=[&](){cache.core_save_success();cache.inventory().inventory_save_success();cache.skills().save_success();cache.quests().save_success();};
        const auto rows=[&](){return db.query("SELECT QuestID,[Delay],Success,Finish,Count1,Count2,Count3 FROM "+prefix+"CharQuests WHERE CharID="+cid+" ORDER BY QuestID;")[0].rows;};
        bool rejected=false;try{quests.save_in_transaction(cache.quests(),created.character_id);}catch(const std::logic_error&){rejected=true;}require(rejected,"Quest phase ran outside character transaction");
        apply(progress(10,100,{7,8,9}));apply(end(11,1));apply(end(12,2));apply(start(20,4));apply(start(30,6));apply(progress(30,8,{1,2,3}));auto counter=packet(0xa05);put(counter,30,2);counter.insert(counter.end(),{1,255});apply(counter);apply(end(30,0));apply(start(40,1));apply(end(40,2));apply(skill(5,30));
        PlayerItem item;item.uid=0x7777000000000500ULL;item.id=5001;item.type=5;item.type_id=1;item.bag=1;item.count=10;item.made_at=pack_world_time(time);item.make_type="U";require(cache.inventory().load(item,false,1),"Cannot seed quest composite inventory");
        require(cache.quests().deleted()==std::vector<std::uint16_t>{12,20},"Quest journal did not suppress transient cancellation");db.begin();save();require(cache.quests().finished().back().save_type==1,"Quest save acknowledged before character commit");db.commit();acknowledge();
        const auto first=rows();require(first.size()==4 && first[0][0]==storage::Cell{"10"} && first[0][1]==storage::Cell{"100"} && first[0][4]==storage::Cell{"7"} && first[1][0]==storage::Cell{"11"} && first[1][1]==storage::Cell{"17"} && first[1][2]==storage::Cell{"1"} && first[1][3]==storage::Cell{"1"} && first[2][0]==storage::Cell{"20"} && first[2][1]==storage::Cell{"4"} && first[2][3]==storage::Cell{"0"} && first[3][0]==storage::Cell{"30"} && first[3][1]==storage::Cell{"0"} && first[3][2]==storage::Cell{"0"} && first[3][3]==storage::Cell{"1"},"Original quest add/modify/finish insert/update contracts changed");
        require(cache.quests().deleted()==std::vector<std::uint16_t>{12,20} && cache.quests().active()[1].save_type==2 && cache.quests().finished().back().save_type==0,"SaveSuccess did not retain original journal/flag behavior");
        apply(skill(6,20));auto count=packet(0x707);count.insert(count.end(),{1,0,4});apply(count);apply(progress(10,101,{3,4,5}));apply(start(32760,1));apply(end(32760,1));
        db.begin();bool failed=false;try{save();}catch(const std::runtime_error&){failed=true;}require(failed && db.transaction_active(),"Later finished-quest failure lost caller transaction");db.rollback();require(rows()==first,"Quest failure retained partial journal deletions or progress");
        auto state=db.query("SELECT SkillPoint FROM "+prefix+"Chars WHERE CharID="+cid+"; SELECT [Count] FROM "+prefix+"CharItems WHERE CharID="+cid+"; SELECT SkillID FROM "+prefix+"CharSkills WHERE CharID="+cid+" ORDER BY SkillID;");require(state[0].rows[0][0]==storage::Cell{"30"} && state[1].rows[0][0]==storage::Cell{"10"} && state[2].rows==std::vector<storage::Row>{{storage::Cell{"5"}}},"Quest failure retained partial core/inventory/skill writes");require(cache.core().skill_points==20 && cache.inventory().inventory()[0].save_type==2 && cache.skills().saved_count()==1 && cache.quests().finished().back().save_type==1 && cache.quests().deleted()==std::vector<std::uint16_t>{12,20},"Rollback discarded pending character/quest state");
        apply(start(32760,1));apply(end(32760,2));db.begin();save();db.commit();acknowledge();const auto retry=rows();require(retry.size()==3 && retry[0][0]==storage::Cell{"10"} && retry[0][1]==storage::Cell{"101"} && retry[1][0]==storage::Cell{"11"} && retry[2][0]==storage::Cell{"30"},"Original retained deletion journal did not remove restarted quest on next save");
        // This original quirk leaves quest 20 in memory after its confirmed SQL row is deleted again.
        require(cache.quests().active().size()==2 && cache.quests().active()[1].id==20 && cache.quests().deleted()==std::vector<std::uint16_t>{12,20},"Native cache silently repaired original retained deletion behavior");
        state=db.query("SELECT SkillPoint FROM "+prefix+"Chars WHERE CharID="+cid+"; SELECT [Count] FROM "+prefix+"CharItems WHERE CharID="+cid+"; SELECT SkillID FROM "+prefix+"CharSkills WHERE CharID="+cid+" ORDER BY SkillID; SELECT QuestID,Success,Finish FROM "+prefix+"CharQuests WHERE CharID="+other_id+";");require(state[0].rows[0][0]==storage::Cell{"20"} && state[1].rows[0][0]==storage::Cell{"4"} && state[2].rows==std::vector<storage::Row>{{storage::Cell{"5"}},{storage::Cell{"6"}}} && state[3].rows[0]==storage::Row{storage::Cell{"99"},storage::Cell{"1"},storage::Cell{"1"}},"Composite retry failed or affected another character");
        apply(progress(10,65535,{1,2,3}));db.begin();failed=false;try{save();}catch(const std::runtime_error&){failed=true;}db.rollback();require(failed && rows()==retry,"Quest WORD delay wrapped instead of failing SQL SMALLINT conversion");apply(progress(10,101,{3,4,5}));apply(start(65535,1));db.begin();failed=false;try{save();}catch(const std::runtime_error&){failed=true;}db.rollback();require(failed && rows()==retry,"Quest WORD ID became a negative SQL identifier");apply(end(65535,2));
        bool allocate=true;QuestReplicaPool controlled([&]()->std::unique_ptr<CachedQuest>{return allocate?std::make_unique<CachedQuest>():nullptr;});QuestReplica other_cache(9302,controlled);require(other_cache.load_finished({99,1}),"Cannot seed allocation-failure completion");allocate=false;require(other_cache.apply(start(99,7,9302))==InventoryReplicaResult::applied && other_cache.active().empty() && other_cache.finished().empty() && other_cache.deleted()==std::vector<std::uint16_t>{99} && controlled.statistics().attempts==2 && controlled.statistics().available==1,"Failed quest start did not consume/recycle the previous completion in source order");db.begin();quests.save_in_transaction(other_cache,other.character_id);db.commit();other_cache.save_success();state=db.query("SELECT COUNT(*) FROM "+prefix+"CharQuests WHERE CharID="+other_id+";");require(state[0].rows[0][0]==storage::Cell{"0"} && other_cache.deleted().size()==1,"Failed-start deletion did not persist/retain its journal");
        std::cout<<"Original quest SQL passed: progress, cancel/finish/restart, retained journals, composite rollback/retry, allocation failure and SMALLINT bounds\n";
    }catch(const std::exception& error) {std::cerr<<error.what()<<'\n';return 1;}
}
